// joinWords joins phrases with commas and a final "and".
func joinWords(parts []string) string {
	switch len(parts) {
	case 0:
		return "all cards"
	case 1:
		return parts[0]
	}
	out := parts[0]
	for i, p := range parts[1:] {
		if i == len(parts)-2 {
			out += " and " + p
		} else {
			out += ", " + p
		}
	}
	return out
}

